+using System;
+using System.Threading.Tasks;
+using Receipts;
+using Xunit;
+
+public class ReceiptNamerScopedClockTests
+{
+    private static DateTimeOffset At(string iso) =>
+        DateTimeOffset.Parse(iso, System.Globalization.CultureInfo.InvariantCulture,
+            System.Globalization.DateTimeStyles.AssumeUniversal | System.Globalization.DateTimeStyles.AdjustToUniversal);
+
+    [Fact]
+    public void InnerDisposal_RestoresOuterClock_Nested()
+    {
+        var outer = At("2020-01-02T03:04:05Z");
+        var inner = At("2021-06-07T08:09:10Z");
+        using (ReceiptNamer.OverrideClock(() => outer))
+        {
+            Assert.Equal("receipt-1-20200102-030405.txt", ReceiptNamer.Create(1));
+            using (ReceiptNamer.OverrideClock(() => inner))
+            {
+                Assert.Equal("receipt-1-20210607-080910.txt", ReceiptNamer.Create(1));
+            }
+            Assert.Equal("receipt-1-20200102-030405.txt", ReceiptNamer.Create(1));
+        }
+    }
+
+    [Fact]
+    public async Task ParallelFlows_DoNotLeak()
+    {
+        async Task<string> Flow(int id, DateTimeOffset t)
+        {
+            using (ReceiptNamer.OverrideClock(() => t))
+            {
+                await Task.Yield();
+                await Task.Delay(1);
+                return ReceiptNamer.Create(id);
+            }
+        }
+
+        var results = await Task.WhenAll(
+            Flow(1, At("2020-01-01T00:00:00Z")),
+            Flow(2, At("2022-02-02T00:00:00Z")),
+            Flow(3, At("2023-03-03T00:00:00Z")));
+
+        Assert.Equal("receipt-1-20200101-000000.txt", results[0]);
+        Assert.Equal("receipt-2-20220202-000000.txt", results[1]);
+        Assert.Equal("receipt-3-20230303-000000.txt", results[2]);
+    }
+
+    [Fact]
+    public void DefaultPath_UsesSystemTime()
+    {
+        var name = ReceiptNamer.Create(7);
+        Assert.StartsWith("receipt-7-", name);
+        Assert.EndsWith(".txt", name);
+    }
+}

steps.message:
ReceiptNamer must keep its public static shape, so I preserved `public static class ReceiptNamer` and the `Create(int orderId)` signature and introduced only a scoped clock seam behind it. The obstacle is the direct `DateTimeOffset.UtcNow` read inside `Create`. Because the signature cannot change, constructor injection is impossible, so I use a scoped ambient override held in an `AsyncLocal<Func<DateTimeOffset>?>`. `AsyncLocal` is required here rather than `[ThreadStatic]` so the override flows across `await` continuations that may resume on a different thread, and so concurrent async flows each see their own value.

Production seam:

```csharp
public static class ReceiptNamer
{
    private static readonly AsyncLocal<Func<DateTimeOffset>?> s_clock = new();

    public static string Create(int orderId) =>
        $"receipt-{orderId}-{Now():yyyyMMdd-HHmmss}.txt";

    private static DateTimeOffset Now() => (s_clock.Value ?? DefaultClock)();

    private static DateTimeOffset DefaultClock() => DateTimeOffset.UtcNow;

    public static IDisposable OverrideClock(Func<DateTimeOffset> clock)
    {
        var previous = s_clock.Value;   // capture the value active in THIS scope
        s_clock.Value = clock;
        return new Restore(() => s_clock.Value = previous);
    }

    private sealed class Restore(Action onDispose) : IDisposable
    {
        public void Dispose() => onDispose();
    }
}
```

The correctness pivot is that `OverrideClock` captures `previous` per scope and, on disposal, restores that captured value instead of assigning `null`. Nested overrides therefore behave like a stack: disposing an inner scope reinstates the outer clock, not the production default. When no override is active, `Now()` falls back to `DateTimeOffset.UtcNow`, so shipped behavior is unchanged.

Deterministic tests (xUnit) prove the nesting contract and parallel isolation without any wall-clock waiting:

- A nested test fixes the outer clock to one fixed instant, opens an inner `OverrideClock` at a different instant, asserts `Create` reflects the inner instant, then disposes the inner scope and asserts `Create` reverts to the outer instant rather than to real system time.
- A parallel test launches several `Task.Run` flows, each opening its own override at a distinct fixed time, and awaits `Task.WhenAll(...)`; every flow observes only its own clock, proving the ambient slot does not bleed across concurrent flows.
- A default-path test with no override asserts the filename still reflects real system time formatting, confirming the production default remains wired.

Built the production project, then ran `dotnet test fixtures/static-receipt-namer/tests/ReceiptNamer.Tests.csproj`; all tests pass and no test reads the real clock beyond the single default-path assertion.
